import { OffsetRange } from '../core/offsetRange.js';
import { AnnotatedStringEdit, AnnotatedStringReplacement, DiffAnnotation } from './annotatedStringEdit.js';
import { DiffResult } from './diffResult.js';
import { Move } from './move.js';
import { OffsetRangeMapping } from './offsetRange.js';
import { StringEdit, StringReplacement } from './stringEdit.js';

/*
 * The flat encoding of a `DiffResult` returned by the wasm module and the worker:
 * `[hitTimeout, nEdits, edit*, nMoves, (oStart, oEnd, mStart, mEnd, nInner, edit*)*]`,
 * where `edit` is `oStart, oEnd, mStart, mEnd, annotation`. New texts are given as ranges
 * of the modified text (for inner edits of a move: of the moved modified text).
 */

const enum FlatAnnotation {
	Change = 0,
	TrimWhitespace = 1,
}

/** @internal */
export function _decodeFlatDiff(flat: Uint32Array, modified: string): DiffResult {
	let i = 0;
	const hitTimeout = flat[i++] === 1;

	const editCount = flat[i++];
	const replacements = new Array<AnnotatedStringReplacement<DiffAnnotation>>(editCount);
	for (let k = 0; k < editCount; k++, i += 5) {
		replacements[k] = new AnnotatedStringReplacement(
			new OffsetRange(flat[i], flat[i + 1]),
			modified.substring(flat[i + 2], flat[i + 3]),
			flat[i + 4] === FlatAnnotation.TrimWhitespace ? DiffAnnotation.trimWhitespace : DiffAnnotation.change,
		);
	}

	const moveCount = flat[i++];
	const moves = new Array<Move>(moveCount);
	for (let k = 0; k < moveCount; k++) {
		const original = new OffsetRange(flat[i], flat[i + 1]);
		const modifiedRange = new OffsetRange(flat[i + 2], flat[i + 3]);
		const innerCount = flat[i + 4];
		i += 5;
		const inner = new Array<StringReplacement>(innerCount);
		for (let j = 0; j < innerCount; j++, i += 5) {
			inner[j] = new StringReplacement(
				new OffsetRange(flat[i], flat[i + 1]),
				modified.substring(modifiedRange.start + flat[i + 2], modifiedRange.start + flat[i + 3]),
			);
		}
		moves[k] = new Move(new OffsetRangeMapping(original, modifiedRange), StringEdit.of(inner));
	}

	return new DiffResult(AnnotatedStringEdit.of(replacements), moves, hitTimeout);
}

/**
 * Inverse of {@link _decodeFlatDiff}. New texts are located by the positions of the edits,
 * which is exact because the edits transform the original text into the modified text.
 * @internal
 */
export function _encodeFlatDiff(result: DiffResult): Uint32Array {
	const out: number[] = [result.hitTimeout ? 1 : 0];
	pushEdits(out, result.edits.replacements.map(r => ({
		range: r.range,
		newText: r.newText,
		annotation: r.data.isTrimWhitespaceChange ? FlatAnnotation.TrimWhitespace : FlatAnnotation.Change,
	})));
	out.push(result.moves.length);
	for (const m of result.moves) {
		out.push(m.range.original.start, m.range.original.endExclusive, m.range.modified.start, m.range.modified.endExclusive);
		pushEdits(out, m.innerEdit.replacements.map(r => ({ range: r.range, newText: r.newText, annotation: FlatAnnotation.Change })));
	}
	return new Uint32Array(out);
}

function pushEdits(out: number[], edits: readonly { range: OffsetRange; newText: string; annotation: FlatAnnotation }[]): void {
	out.push(edits.length);
	let delta = 0;
	for (const e of edits) {
		const modifiedStart = e.range.start + delta;
		out.push(e.range.start, e.range.endExclusive, modifiedStart, modifiedStart + e.newText.length, e.annotation);
		delta += e.newText.length - e.range.length;
	}
}
