import type { DiffOptions } from '../api/diffResult.js';
import type { WasmModule } from './types.js';

const encoder = new TextEncoder();

/**
 * Diffs two texts with the wasm module and returns its flat result (see {@link WasmModule.computeDiff}).
 * The texts are written to wasm memory as UTF-16 code units, so lone surrogates survive.
 */
export function computeWasmDiff(wasm: WasmModule, original: string, modified: string, options: DiffOptions | undefined): Uint32Array {
	const address = wasm.inputBuffer(original.length + modified.length);
	// Read `memory.buffer` only now: allocating can grow the memory, which detaches the previous buffer.
	const buffer = wasm.memory.buffer;
	const originalAsciiPrefixLength = writeUtf16(buffer, address, original);
	const modifiedAsciiPrefixLength = writeUtf16(buffer, address + 2 * original.length, modified);
	return wasm.computeDiff(
		original.length,
		originalAsciiPrefixLength,
		modified.length,
		modifiedAsciiPrefixLength,
		options?.maxComputationTimeMs ?? 0,
		options?.computeMoves ?? false,
		options?.extendToSubwords ?? false,
	);
}

/**
 * Writes the code units of `text` to `2 * text.length` bytes at `address`. The ASCII prefix is
 * written as bytes by `encodeInto` (fast) and widened by wasm; the rest as code units.
 * Returns the length of the ASCII prefix.
 */
function writeUtf16(buffer: ArrayBuffer, address: number, text: string): number {
	const bytes = new Uint8Array(buffer, address, text.length);
	const { read, written } = encoder.encodeInto(text, bytes);
	// One byte per code unit means everything read so far was ASCII.
	const asciiPrefixLength = read === written ? read : firstNonAscii(bytes, written);
	if (asciiPrefixLength < text.length) {
		const units = new Uint16Array(buffer, address, text.length);
		for (let i = asciiPrefixLength; i < text.length; i++) {
			units[i] = text.charCodeAt(i);
		}
	}
	return asciiPrefixLength;
}

function firstNonAscii(bytes: Uint8Array, length: number): number {
	for (let i = 0; i < length; i++) {
		if (bytes[i] >= 0x80) {
			return i;
		}
	}
	return length;
}
